<template><section><header class="page-head"><div><p class="eyebrow">REPAIR CENTER</p><h2>报修管理</h2></div><el-button type="primary" @click="dialog=true">提交报修</el-button></header><div class="toolbar"><el-select v-model="status" placeholder="全部状态" clearable @change="load"><el-option v-for="(t,k) in repairStatusText" :key="k" :label="t" :value="k"/></el-select><el-select v-model="overdue" placeholder="全部响应" clearable @change="load"><el-option label="仅超时工单" :value="true"/><el-option label="仅未超时" :value="false"/></el-select></div><div class="repair-list"><RepairCard v-for="v in items" :key="v.id" :repair="v" @changed="load"/><EmptyState v-if="!items.length"/></div><el-dialog v-model="dialog" title="提交报修工单"><el-form label-width="84px"><el-form-item label="报修标题"><el-input v-model="form.title" placeholder="报修标题"/></el-form-item><el-form-item label="问题描述"><el-input v-model="form.description" type="textarea" placeholder="问题描述"/></el-form-item><el-form-item label="报修类型"><el-select v-model="form.type"><el-option label="水电" value="水电"/><el-option label="家具" value="家具"/><el-option label="公共设施" value="公共设施"/><el-option label="其他" value="其他"/></el-select></el-form-item><el-form-item label="紧急等级"><el-radio-group v-model="form.priority"><el-radio v-for="(t,k) in repairPriorityText" :key="k" :value="k">{{t}} · {{repairPriorityDeadlineText[k as RepairPriority]}}</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">提交</el-button></template></el-dialog></section></template><script setup lang="ts">import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{listRepairs,createRepair}from'../api/repair';import{repairStatusText,repairPriorityText,repairPriorityDeadlineText}from'../constants/repair';import type{Repair,RepairPriority}from'../types';import RepairCard from'../components/common/RepairCard.vue';import EmptyState from'../components/common/EmptyState.vue';const items=ref<Repair[]>([]),status=ref(''),overdue=ref<boolean|undefined>(undefined),dialog=ref(false),form=ref<{title:string;description:string;type:string;images:string;priority:RepairPriority}>({title:'',description:'',type:'水电',images:'',priority:'normal'});async function load(){items.value=await listRepairs({status:status.value||undefined,overdue:overdue.value})}async function submit(){try{await createRepair(form.value);ElMessage.success('报修工单已提交');dialog.value=false;form.value={title:'',description:'',type:'水电',images:'',priority:'normal'};load()}catch(e){ElMessage.error((e as Error).message)}}onMounted(load)</script>
